import React from "react";

const SlotCard = ({ slotData, isOccupied }) => {
  // Format the timestamp if it exists
  const entryTime = slotData?.created_at 
    ? new Date(slotData.created_at).toLocaleTimeString() 
    : "--:--";

  const entryDate = slotData?.created_at
    ? new Date(slotData.created_at).toLocaleDateString()
    : "";

  return (
    <div className={`slot-card ${isOccupied ? "occupied" : "available"}`}>
      
      {/* 1. SLOT TITLE */}
      <div className="slot-name">
        {isOccupied ? "SLOT 1 - BUSY" : "SLOT 1 - FREE"}
      </div>

      {/* 2. STATUS TEXT */}
      <div className="slot-status">
        {isOccupied ? "Occupied" : "Available"}
      </div>

      {/* 3. DETAILS (Only show if occupied) */}
      {isOccupied && (
        <div className="slot-details" style={{ marginTop: '20px', textAlign: 'center' }}>
          
          {/* Plate Number in big neon text */}
          <div style={{ color: '#fff', fontSize: '28px', fontWeight: 'bold', letterSpacing: '2px' }}>
            {slotData.plate || "UNKNOWN"}
          </div>
          
          {/* Entry Time */}
          <div style={{ color: '#ccc', fontSize: '14px', marginTop: '5px' }}>
            Entered at: {entryTime} <br/>
            <span style={{ fontSize:'12px', color:'#888'}}>{entryDate}</span>
          </div>

        </div>
      )}

    </div>
  );
};

export default SlotCard;
